func (m *PrivateKey) cloneKanon(c *PrivateKey) {
	c.id = m.id
	c.Name = strings.Clone(m.Name)
}

// PrivateKeyView is the encoding of a PrivateKey. Each method reads one field
// by scanning the encoding, without decoding the rest, and returns the zero
// value when the encoding has no such field, and the last value when it has
// several. A method of a struct fails with kanon.ErrRepeatedView for a second
// occurrence instead, since a decode merges the occurrences. The bytes that a
// method returns for a string, a byte slice and a struct alias the view. A
// value of a type that encodes itself decodes with the method of its type, and
// the offsets of the errors of a method are offsets in the view.
type PrivateKeyView []byte

// Name returns the value of the field Name of the encoding in v.
func (v PrivateKeyView) Name() ([]byte, error) {
	i, err := wire.Find(v, 2<<3|wire.Bytes, "PrivateKey.Name")
	if err != nil || i < 0 {
		return nil, err
	}
	l, n := wire.Uvarint(v[i:])
	return []byte(v[i+n : i+n+int(l)]), nil
}

// _private_sizeSliceString returns the length of the encoding of the elements
// of x, a []string.
func _private_sizeSliceString(x []string) int {
	n := 0
	for k := range x {
		n += wire.SizeBytes(len(x[k]))
	}
	return n
}

// _private_sizeMapPrivateKeyString returns the length of the encoding of the
// keys and values of x, a map[PrivateKey]string.
func _private_sizeMapPrivateKeyString(x map[PrivateKey]string) int {
	n := 0
	var mk PrivateKey
	var mv string
	for mk, mv = range x {
		n += wire.SizeBytes(mk.SizeKanon()) + wire.SizeBytes(len(mv))
	}
	return n
}

// _private_sizePrivateDetail returns the length of the encoding of the
// privateDetail that m points at.
func _private_sizePrivateDetail(m *privateDetail) int {
	n := 0
	if m.label != "" {
		n += 1 + wire.SizeBytes(len(m.label))
	}
	if m.Rank != 0 {
		n += 1 + wire.SizeUvarint(wire.Zigzag(int64(m.Rank)))
	}
	return n
}

// _private_putPrivateDetail writes the encoding of the privateDetail that m
// points at into the end of buf, which has room for it, and returns its length.
func _private_putPrivateDetail(buf []byte, m *privateDetail) int {
	i := len(buf)
	if m.Rank != 0 {
		i = wire.PutUvarint(buf, i, wire.Zigzag(int64(m.Rank)))
		i = wire.PutTag(buf, i, 2<<3|wire.Varint)
	}
	if m.label != "" {
		i = wire.PutRaw(buf, i, m.label)
		i = wire.PutUvarint(buf, i, uint64(len(m.label)))
		i = wire.PutTag(buf, i, 1<<3|wire.Bytes)
	}
	return len(buf) - i
}

// _private_putMapPrivateKeyString writes the encoding of x, a
// map[PrivateKey]string, into the end of buf, which has room for it, and
// returns its length.
func _private_putMapPrivateKeyString(buf []byte, x map[PrivateKey]string) int {
	i := len(buf)
	type pair = wire.Pair[PrivateKey, string]
	var arr [16]pair
	pairs := arr[:0]
	for mk, mv := range x {
		pairs = append(pairs, pair{Key: mk, Value: mv})
	}
	slices.SortFunc(pairs, func(a, b pair) int {
		return _private_comparePrivateKey(a.Key, b.Key)
	})
	for k := len(pairs) - 1; k >= 0; k-- {
		i = wire.PutRaw(buf, i, pairs[k].Value)
		i = wire.PutUvarint(buf, i, uint64(len(pairs[k].Value)))
		{
			w, _ := pairs[k].Key.encodeKanon(buf[:i])
			i -= w
			i = wire.PutUvarint(buf, i, uint64(w))
		}
	}
	i = wire.PutUvarint(buf, i, uint64(len(buf)-i))
	return len(buf) - i
}

// _private_putSliceString writes the encoding of x, a []string, into the end of
// buf, which has room for it, and returns its length.
func _private_putSliceString(buf []byte, x []string) int {
	i := len(buf)
	for k := len(x) - 1; k >= 0; k-- {
		i = wire.PutRaw(buf, i, x[k])
		i = wire.PutUvarint(buf, i, uint64(len(x[k])))
	}
	i = wire.PutUvarint(buf, i, uint64(len(buf)-i))
	return len(buf) - i
}

// _private_resetPrivateDetail clears the privateDetail that m points at and
// keeps the memory that a decode reuses, as Reset does.
func _private_resetPrivateDetail(m *privateDetail) {
	m.label = ""
	m.Rank = 0
}

// _private_readSliceString appends the elements that data encodes, a []string
// without its length, to *dst. data starts at offset off of slab, and the
// decode enters depth levels below the value at most. loc and num locate the
// field in errors.
func _private_readSliceString(dst *[]string, data []byte, slab string, off, depth int, loc string, num int) error {
	if depth < 0 {
		return wire.DepthError(loc, num, off)
	}
	x := *dst
	if x == nil && len(data) > 0 {
		x = make([]string, 0, wire.CountValues(data))
	}
	for i := 0; i < len(data); {
		x = append(x, "")
		last := len(x) - 1
		l, n := wire.Uvarint(data[i:])
		if n <= 0 || uint64(len(data)-i-n) < l {
			return wire.ReadError(n, loc, num, off+i)
		}
		i += n
		x[last] = slab[off+i : off+i+int(l)]
		i += int(l)
	}
	*dst = x
	return nil
}

// _private_readMapPrivateKeyString adds the entries that data encodes, a
// map[PrivateKey]string without its length, to *dst. With collect set, it
// clears *dst first, and the entries reuse the memory of up to 16 of its
// values. data starts at offset off of slab, and the decode enters depth levels
// below the value at most. loc and num locate the field in errors.
func _private_readMapPrivateKeyString(dst *map[PrivateKey]string, data []byte, slab string, off, depth int, collect bool, loc string, num int) error {
	if depth < 0 {
		return wire.DepthError(loc, num, off)
	}
	x := *dst
	if collect {
		clear(x)
	}
	if x == nil && len(data) > 0 {
		x = make(map[PrivateKey]string)
		*dst = x
	}
	var mk PrivateKey
	var mv string
	for i := 0; i < len(data); {
		{
			l, n := wire.Uvarint(data[i:])
			if n <= 0 || uint64(len(data)-i-n) < l {
				return wire.ReadError(n, loc, num, off+i)
			}
			i += n
			if depth < 1 {
				return wire.DepthError("PrivateKey", 0, off+i)
			}
			if err := mk.decodeKanon(data[i:i+int(l)], slab, off+i, depth-1); err != nil {
				return err
			}
			i += int(l)
		}
		{
			l, n := wire.Uvarint(data[i:])
			if n <= 0 || uint64(len(data)-i-n) < l {
				return wire.ReadError(n, loc, num, off+i)
			}
			i += n
			mv = slab[off+i : off+i+int(l)]
			i += int(l)
		}
		x[mk] = mv
	}
	return nil
}

// _private_readPrivateDetail sets the privateDetail that m points at to the
// value encoded in data and reuses its memory, as DecodeKanon does. data starts
// at offset off of slab, and the decode enters depth levels below the value at
// most.
func _private_readPrivateDetail(m *privateDetail, data []byte, slab string, off, depth int) error {
	m.label = ""
	m.Rank = 0
	return _private_mergePrivateDetail(m, data, slab, off, depth)
}

// _private_mergePrivateDetail merges the encoding in data, which starts at
// offset off of slab, into the privateDetail that m points at, as MergeKanon
// does. The decode enters depth levels below m at most.
func _private_mergePrivateDetail(m *privateDetail, data []byte, slab string, off, depth int) error {
	for i := 0; i < len(data); {
		at := i
		tag, n := wire.Uvarint(data[i:])
		if n <= 0 {
			return wire.ReadError(n, "privateDetail", 0, off+i)
		}
		i += n
		switch tag >> 3 {
		case 1:
			if tag != 1<<3|wire.Bytes {
				return wire.FormatError(tag, wire.Bytes, "privateDetail.label", off+at)
			}
			l, n := wire.Uvarint(data[i:])
			if n <= 0 || uint64(len(data)-i-n) < l {
				return wire.ReadError(n, "privateDetail.label", 1, off+i)
			}
			i += n
			m.label = slab[off+i : off+i+int(l)]
			i += int(l)
		case 2:
			if tag != 2<<3|wire.Varint {
				return wire.FormatError(tag, wire.Varint, "privateDetail.Rank", off+at)
			}
			u, n := wire.Uvarint(data[i:])
			if n <= 0 {
				return wire.ReadError(n, "privateDetail.Rank", 2, off+i)
			}
			s := wire.Unzigzag(u)
			if s != int64(int32(s)) {
				return wire.RangeError(s, "int32", "privateDetail.Rank", 2, off+i)
			}
			m.Rank = int32(s)
			i += n
		default:
			n, err := wire.Skip(data[i:], tag, "privateDetail", 0, off+at)
			if err != nil {
				return err
			}
			i += n
		}
	}
	return nil
}

// _private_deselectPrivateKind zeroes the member of the union of Private.Kind
// that the discriminator selects.
func _private_deselectPrivateKind(m *Private) {
	switch m.Kind {
	case PrivateKindText:
		m.text = ""
	case PrivateKindNumber:
		m.number = 0
	}
}

// _private_cloneSliceString returns a copy of x, a []string, and nil for a nil
// x.
func _private_cloneSliceString(x []string) []string {
	if x == nil {
		return nil
	}
	c := make([]string, len(x))
	for k := range x {
		c[k] = strings.Clone(x[k])
	}
	return c
}

// _private_cloneMapPrivateKeyString returns a copy of x, a
// map[PrivateKey]string, and nil for a nil x.
func _private_cloneMapPrivateKeyString(x map[PrivateKey]string) map[PrivateKey]string {
	if x == nil {
		return nil
	}
	c := make(map[PrivateKey]string, len(x))
	for mk, mv := range x {
		var ck PrivateKey
		mk.cloneKanon(&ck)
		c[ck] = strings.Clone(mv)
	}
	return c
}

// _private_clonePtrPrivate returns a pointer to a copy of the value that x, a
// *Private, points at, and nil for a nil x.
func _private_clonePtrPrivate(x *Private) *Private {
	if x == nil {
		return nil
	}
	return x.CloneKanon()
}

// _private_clonePrivateDetail copies the privateDetail that src points at into
// the one that dst points at, as CloneKanon does.
func _private_clonePrivateDetail(dst, src *privateDetail) {
	dst.label = strings.Clone(src.label)
	dst.Rank = src.Rank
}

// _private_comparePrivateKey returns -1, 0 or +1 as the map key a sorts before,
// with or after b, two keys of type PrivateKey.
func _private_comparePrivateKey(a, b PrivateKey) int {
	if c := cmp.Compare(a.id, b.id); c != 0 {
		return c
	}
	return cmp.Compare(a.Name, b.Name)
}
